import { describe, it, expect } from "vitest";
import { Test } from "@nestjs/testing";
import { NotificationsModule } from "../notifications/notifications.module.js";
import { NotificationsService } from "../notifications/notifications.service.js";
import { CourseCatalog } from "./course-catalog.js";
import { EnrollmentRepository } from "./enrollment.repository.js";
import { EnrollmentService } from "./enrollment.service.js";

async function setup() {
  const moduleRef = await Test.createTestingModule({
    imports: [NotificationsModule],
    providers: [CourseCatalog, EnrollmentRepository, EnrollmentService],
  }).compile();
  return { enrollment: moduleRef.get(EnrollmentService), notifications: moduleRef.get(NotificationsService) };
}

describe("EnrollmentService", () => {
  it("confirms an enrollment while seats are left and notifies the student", async () => {
    const { enrollment, notifications } = await setup();
    const e = enrollment.enroll({ studentId: "stu-ada", courseId: "crs-poetry" });
    expect(e).toEqual({ id: "enr-1", studentId: "stu-ada", courseId: "crs-poetry", status: "confirmed" });
    expect(notifications.forRecipient("stu-ada")).toEqual([
      { id: "ntf-1", recipientId: "stu-ada", kind: "enrollment-confirmed", enrollmentId: "enr-1", message: "You are enrolled in Modern Poetry." },
    ]);
    expect(enrollment.courses().find((c) => c.id === "crs-poetry")?.seatsLeft).toBe(0);
  });

  it("rejects an enrollment into a full course and notifies the student", async () => {
    const { enrollment, notifications } = await setup();
    enrollment.enroll({ studentId: "stu-ada", courseId: "crs-poetry" });
    const e = enrollment.enroll({ studentId: "stu-bob", courseId: "crs-poetry" });
    expect(e).toMatchObject({ status: "rejected", reason: "COURSE_FULL" });
    expect(notifications.forRecipient("stu-bob")).toEqual([
      expect.objectContaining({ kind: "enrollment-rejected", enrollmentId: e.id }),
    ]);
  });

  it("rejects a repeat enrollment without taking a second seat", async () => {
    const { enrollment } = await setup();
    enrollment.enroll({ studentId: "stu-ada", courseId: "crs-algebra" });
    expect(enrollment.enroll({ studentId: "stu-ada", courseId: "crs-algebra" })).toMatchObject({ status: "rejected", reason: "ALREADY_ENROLLED" });
    expect(enrollment.courses().find((c) => c.id === "crs-algebra")?.seatsLeft).toBe(1);
  });

  it("refuses an unknown course without recording or notifying anything", async () => {
    const { enrollment, notifications } = await setup();
    expect(() => enrollment.enroll({ studentId: "stu-ada", courseId: "crs-missing" })).toThrow("unknown course crs-missing");
    expect(notifications.forRecipient("stu-ada")).toEqual([]);
  });
});
import { describe, it, expect, beforeEach, afterEach } from "vitest";
import type { INestApplication } from "@nestjs/common";
import { Test } from "@nestjs/testing";
import request from "supertest";
import { AppModule } from "../src/app.module.js";
import { configureApp } from "../src/app.setup.js";

describe("Course Desk API (e2e)", () => {
  let app: INestApplication;

  beforeEach(async () => {
    const moduleRef = await Test.createTestingModule({ imports: [AppModule] }).compile();
    app = configureApp(moduleRef.createNestApplication());
    await app.init();
  });

  afterEach(async () => {
    await app.close();
  });

  it("lists the seeded courses with free seats", async () => {
    const res = await request(app.getHttpServer()).get("/api/courses").expect(200);
    expect(res.body).toEqual([
      { id: "crs-algebra", title: "Linear Algebra", capacity: 2, seatsLeft: 2 },
      { id: "crs-poetry", title: "Modern Poetry", capacity: 1, seatsLeft: 1 },
    ]);
  });

  it("confirms, then rejects when full; each student is notified of their outcome", async () => {
    const server = app.getHttpServer();
    const first = await request(server).post("/api/enrollments").send({ studentId: "stu-ada", courseId: "crs-poetry" }).expect(201);
    expect(first.body).toEqual({ id: "enr-1", studentId: "stu-ada", courseId: "crs-poetry", status: "confirmed" });

    const second = await request(server).post("/api/enrollments").send({ studentId: "stu-bob", courseId: "crs-poetry" }).expect(201);
    expect(second.body).toEqual({ id: "enr-2", studentId: "stu-bob", courseId: "crs-poetry", status: "rejected", reason: "COURSE_FULL" });

    await request(server).get("/api/enrollments/enr-2").expect(200, second.body);

    const ada = await request(server).get("/api/notifications").query({ recipientId: "stu-ada" }).expect(200);
    expect(ada.body).toEqual([{ id: "ntf-1", recipientId: "stu-ada", kind: "enrollment-confirmed", enrollmentId: "enr-1", message: "You are enrolled in Modern Poetry." }]);
    const bob = await request(server).get("/api/notifications").query({ recipientId: "stu-bob" }).expect(200);
    expect(bob.body).toEqual([
      { id: "ntf-2", recipientId: "stu-bob", kind: "enrollment-rejected", enrollmentId: "enr-2", message: "Modern Poetry is full; your enrollment was not accepted." },
    ]);
  });

  it("answers 400 for an invalid request and 404 for unknown courses or enrollments", async () => {
    const server = app.getHttpServer();
    await request(server).post("/api/enrollments").send({ studentId: "" }).expect(400);
    await request(server).post("/api/enrollments").send({ studentId: "stu-ada", courseId: "crs-missing" }).expect(404);
    await request(server).get("/api/enrollments/enr-99").expect(404);
    await request(server).get("/api/notifications").expect(400);
  });
});
import { cleanup, fireEvent, render, screen } from "@testing-library/react";
import { afterEach, describe, expect, it, vi } from "vitest";
import { App } from "./App";
import { httpApi } from "./api/client";
import type { CourseDeskApi, Enrollment, Notification } from "./api/client";

afterEach(cleanup);

/** A fake API with the server's observable behavior for one course with one seat. */
function fakeApi(): CourseDeskApi {
  const enrollments: Enrollment[] = [];
  const notifications: Notification[] = [];
  const confirmed = () => enrollments.filter((e) => e.status === "confirmed").length;
  return {
    courses: async () => [{ id: "crs-poetry", title: "Modern Poetry", capacity: 1, seatsLeft: 1 - confirmed() }],
    enroll: async (studentId, courseId) => {
      const full = confirmed() >= 1;
      const e: Enrollment = { id: `enr-${enrollments.length + 1}`, studentId, courseId, status: full ? "rejected" : "confirmed", ...(full ? { reason: "COURSE_FULL" as const } : {}) };
      enrollments.push(e);
      notifications.push({
        id: `ntf-${notifications.length + 1}`,
        recipientId: studentId,
        kind: full ? "enrollment-rejected" : "enrollment-confirmed",
        enrollmentId: e.id,
        message: full ? "Modern Poetry is full; your enrollment was not accepted." : "You are enrolled in Modern Poetry.",
      });
      return e;
    },
    notifications: async (recipientId) => notifications.filter((n) => n.recipientId === recipientId),
  };
}

describe("App", () => {
  it("shows the outcome and the student's notification after enrolling, then a rejection when full", async () => {
    render(<App api={fakeApi()} />);
    await screen.findByRole("option", { name: "Modern Poetry (1 of 1 seats left)" });

    fireEvent.click(screen.getByRole("button", { name: "Enroll" }));
    expect((await screen.findByRole("status")).textContent).toBe("Enrollment enr-1: confirmed");
    expect(await screen.findByText("You are enrolled in Modern Poetry.")).toBeTruthy();
    await screen.findByRole("option", { name: "Modern Poetry (0 of 1 seats left)" });

    fireEvent.change(screen.getByLabelText("Student ID"), { target: { value: "stu-bob" } });
    fireEvent.click(screen.getByRole("button", { name: "Enroll" }));
    await screen.findByText("Enrollment enr-2: rejected (COURSE_FULL)");
    expect(await screen.findByText("Modern Poetry is full; your enrollment was not accepted.")).toBeTruthy();
    expect(screen.getByRole("heading", { name: "Notifications for stu-bob" })).toBeTruthy();
  });
});

describe("httpApi", () => {
  it("posts enrollments as JSON to the server's routes", async () => {
    const fetchImpl = vi.fn(async () => new Response(JSON.stringify({ id: "enr-1" }), { status: 201 }));
    await httpApi("/api", fetchImpl as unknown as typeof fetch).enroll("stu-ada", "crs-poetry");
    expect(fetchImpl).toHaveBeenCalledWith("/api/enrollments", {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({ studentId: "stu-ada", courseId: "crs-poetry" }),
    });
  });

  it("surfaces HTTP errors", async () => {
    const fetchImpl = async () => new Response("{}", { status: 404, statusText: "Not Found" });
    await expect(httpApi("/api", fetchImpl as typeof fetch).notifications("x")).rejects.toThrow("404 Not Found");
  });
});
  "scripts": {
    "build": "npm run build --workspaces",
    "typecheck": "npm run typecheck --workspaces",
    "test": "npm test --workspaces",
    "start": "npm start -w server",
    "dev:web": "npm run dev -w web",
    "smoke": "node scripts/smoke.mjs"
  }
}

